"""A self-contained offline HTML report; all results are computed in Python."""
import json


def build_report(analysis: dict) -> str:
    # Escape embedded JSON so even a literal </script> in a source record is
    # inert. All record values are rendered through textContent or HTML escaping.
    payload = json.dumps(analysis, separators=(",", ":"), ensure_ascii=False)
    payload = payload.replace("<", "\\u003c").replace(">", "\\u003e").replace("&", "\\u0026")
    return TEMPLATE.replace("__PAYLOAD__", payload)


